local ConfigSourceProvider = require(script.ConfigSourceProvider)
local LoggerManger: ILoggerManager = require(game.ReplicatedStorage.Packages.LoggerManager)
local logger = LoggerManger.GetLogger("TangSeng")

-- 从根目录加载配置, 该目录下所有的 ModuleScript 且被 configs.json 定义过后， 将被作为配置源
local function ConfigureAppConfigurationFromRoot(
	root: Instance,
	hostBuilderContext: IHostBuilderContext,
	configurationBuilder: IConfigurationBuilder,
	deserializer: (data: any) -> {}
)
	local children = root:GetDescendants()

	for _, child in ipairs(children) do
		local configSource = ConfigSourceProvider(child, deserializer)
		if not configSource then
			continue
		end
		configurationBuilder:Add(configSource)
	end
end

return ConfigureAppConfigurationFromRoot
